// Brute-force reference over a bounded window, independent of src/
const input = [[0,0],[1,0],[2,0],[1,2]];
const isLive = (x,y) => input.some(([a,b]) => a===x && b===y);
const count = (x,y) => {
  let n = 0;
  for (let dx=-1; dx<=1; dx++) for (let dy=-1; dy<=1; dy++) {
    if (dx===0 && dy===0) continue;
    if (isLive(x+dx, y+dy)) n++;
  }
  return n;
};
const out = [];
for (let x=-4; x<=6; x++) for (let y=-4; y<=6; y++) {
  const c = count(x,y);
  if (isLive(x,y) ? (c===2||c===3) : c===3) out.push([x,y]);
}
