import { nextGeneration } from './src/game-of-life.ts';
const naive = (input) => {
  const isLive = (x,y) => input.some(([a,b]) => a===x && b===y);
  const cnt = (x,y) => { let n=0; for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){if(!dx&&!dy)continue;if(isLive(x+dx,y+dy))n++;} return n; };
  const out=[];
  for(let x=-12;x<=12;x++)for(let y=-12;y<=12;y++){const c=cnt(x,y);if(isLive(x,y)?(c===2||c===3):c===3)out.push([x,y]);}
  return out;
};
const norm = cs => JSON.stringify([...cs].sort((a,b)=>a[0]-b[0]||a[1]-b[1]));
let seed=42; const rnd=()=>((seed=seed*1103515245+12345&0x7fffffff)/0x7fffffff);
let fail=0;
for(let t=0;t<300;t++){
  const n=1+Math.floor(rnd()*12), set=new Set(), cells=[];
  for(let i=0;i<n;i++){const x=Math.floor(rnd()*11)-5,y=Math.floor(rnd()*11)-5,k=x+','+y;if(!set.has(k)){set.add(k);cells.push([x,y]);}}
  if(norm(nextGeneration(cells))!==norm(naive(cells))){fail++;console.log('MISMATCH',JSON.stringify(cells));}
}
console.log(fail===0?'All 300 random boards match the naive reference':`${fail} mismatches`);
EOF
